import { useEffect, useState } from 'react'
import { UserPlus, Users } from 'lucide-react'
import { staffApi, tenantApi, type Staff, type Store, type Vendor } from '../../api'
import { Button } from '../../components/ui/button'
import { Card, CardContent } from '../../components/ui/card'
import { Input } from '../../components/ui/input'

export function StaffPage({ vendor }: { vendor?: Vendor }) { const [staff, setStaff] = useState<Staff[]>([]); const [stores, setStores] = useState<Store[]>([]); const [form, setForm] = useState({ username: '', password: '', displayName: '', role: 'STAFF' }); const [message, setMessage] = useState(''); const load = () => { if (vendor) { staffApi.list(vendor.id).then(setStaff).catch(() => setStaff([])); tenantApi.stores(vendor.id).then(setStores).catch(() => setStores([])) } }; useEffect(load, [vendor]); async function create() { if (!vendor) return; try { await staffApi.create(vendor.id, { ...form, storeIds: stores.map(store => store.id) }); setMessage('Staff account created.'); setForm({ username: '', password: '', displayName: '', role: 'STAFF' }); load() } catch (error) { setMessage(error instanceof Error ? error.message : 'Unable to create staff account.') } } async function toggle(member: Staff) { if (!vendor) return; try { await staffApi.status(vendor.id, member.id, member.enabled ? 'DISABLED' : 'ACTIVE'); load() } catch (error) { setMessage(error instanceof Error ? error.message : 'Unable to update staff status.') } } return <><PageIntro title="Staff" text="Create and manage vendor staff accounts and their access to store operations." />{message && <p className="mb-4 rounded-xl bg-indigo-50 p-3 text-sm font-semibold text-indigo-700">{message}</p>}<div className="grid gap-5 xl:grid-cols-[330px_1fr]"><Card><CardContent className="p-5"><UserPlus className="text-indigo-600" size={20} /><h2 className="mt-3 font-bold">Add staff</h2><div className="mt-4 space-y-3"><Input placeholder="Display name" value={form.displayName} onChange={event => setForm({ ...form, displayName: event.target.value })} /><Input placeholder="Username" value={form.username} onChange={event => setForm({ ...form, username: event.target.value })} /><Input type="password" placeholder="Temporary password" value={form.password} onChange={event => setForm({ ...form, password: event.target.value })} /><select className="w-full rounded-lg border border-slate-200 px-2 py-2 text-xs" value={form.role} onChange={event => setForm({ ...form, role: event.target.value })}><option value="STAFF">Staff</option><option value="VENDOR_ADMIN">Vendor Admin</option></select><Button className="w-full" onClick={create}>Create staff</Button></div></CardContent></Card><Card><CardContent className="p-4"><div className="mb-4 flex items-center gap-2"><Users size={18} className="text-indigo-600" /><h2 className="font-bold">Team members</h2></div><div className="space-y-2">{staff.map(member => <div key={member.id} className="flex flex-col justify-between gap-3 rounded-xl border border-slate-100 p-4 sm:flex-row sm:items-center"><div><strong className="block text-sm">{member.displayName}</strong><span className="text-xs text-slate-500">{member.username} · {member.roles.join(', ')}</span></div><div className="flex items-center gap-2"><span className={`rounded-full px-2.5 py-1 text-[10px] font-bold ${member.enabled ? 'bg-emerald-50 text-emerald-700' : 'bg-slate-100 text-slate-500'}`}>{member.enabled ? 'ACTIVE' : 'DISABLED'}</span><Button size="sm" variant="secondary" onClick={() => toggle(member)}>{member.enabled ? 'Disable' : 'Enable'}</Button></div></div>)}{!staff.length && <p className="p-8 text-center text-sm text-slate-500">No staff accounts found.</p>}</div></CardContent></Card></div></> }
function PageIntro({ title, text }: { title: string; text: string }) { return <div className="mb-6"><p className="text-[11px] font-bold uppercase tracking-[.17em] text-indigo-600">Team management</p><h1 className="mt-1.5 text-3xl font-black tracking-[-.055em]">{title}</h1><p className="mt-2 text-[13px] text-slate-500">{text}</p></div> }
